import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"宿主服务","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/sdk/services.md","filePath":"zh-CN/dev-guide/sdk/services.md","lastUpdated":1785467127000}'),r={name:"zh-CN/dev-guide/sdk/services.md"};function a(i,e,s,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="宿主服务" tabindex="-1">宿主服务 <a class="header-anchor" href="#宿主服务" aria-label="Permalink to &quot;宿主服务&quot;">​</a></h1><p><code>PluginSdk.Services</code> 里的静态服务，把宿主应用的功能暴露给插件——每一个都是包装了宿主启动时接好的委托的薄静态类，所以不管底层实际运行的是什么，插件的调用方式都一样。</p><table tabindex="0"><thead><tr><th>服务</th><th>用途</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> —— <code>text</code>(或它的某个别名)是否匹配 fzf 语法的 <code>pattern</code>,用的是和宿主自身搜索完全一致的匹配逻辑;<code>GetHighlightMask(text, query)</code> —— 对应这一对 (text, query) 的逐字符高亮掩码,用的是宿主自己那套字面量/模糊/别名多级兜底算法(含中文拼音),这样插件自己结果的高亮就能和其他结果保持一致,而不是只能处理简单的字面量子串匹配。</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> 在运行时按当前语言查询;<code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 加载插件自己内嵌的 JSON 语言包;<code>GetSupportedCultures(assembly)</code>;<code>GetCurrentCulture()</code> —— 应用当前选定的界面语言(比如 <code>&quot;zh-CN&quot;</code>),这是一个独立于操作系统语言的用户设置。只有你确实需要拿到原始语言代码本身时才用它(比如塞进 HTTP 的 <code>Accept-Language</code> 请求头,或者决定翻译 API 的目标语言)——<code>CultureInfo.CurrentUICulture</code> 反映的是操作系统的语言,不是这个设置,一旦用户的 Windows 语言和应用内语言不一致,两者就会悄悄对不上。</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> 和 <code>GetThumbnail(path, size)</code> —— 带缓存的 Shell 图标/缩略图提取，插件不需要自己调 Windows 图标 API。</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> —— 只读访问用户的<a href="./../../user-guide/settings/favorites.html">收藏夹</a>列表(<code>FavoriteItem</code>:Name、Path)。</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> —— 每一条已记录的<a href="./../../user-guide/settings/history.html">历史记录</a>条目,按最近打开优先排序,类型是 <code>HistoryEntry { Keyword, Path, Kind, Time }</code>(<code>Kind</code> 是 <code>HistoryEntryKind</code>:<code>File</code> / <code>Folder</code> / <code>Application</code>;<code>Keyword</code> 是打开时输入框里的搜索文字,没打字直接从初始面板点开的话就是空字符串;<code>Time</code> 是 Unix 秒)。同一个路径最多只会出现一次,归属于最近一次带它进来的那个关键字。</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> —— 批量查询 Size/Created/Modified/Accessed(<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>)，用于查询<strong>不属于</strong>你当前结果集的路径——每个 <code>ISearchResult</code> 本身就通过自己的 <code>Metadata</code> 属性免费携带这些数据(参见<a href="./abstractions.html#isearchresult">共享抽象契约</a>)，所以只有拿到的路径不是来自结果对象(比如来自你自己的配置)时才需要用这个服务。</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> / <code>NotifyDirectoryChanged(pluginId)</code> —— 让插件注册自己的目录进行后台索引和 USN 监听，而不用自己重新实现这套机制。</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> —— 从宿主的配置存储里只读访问插件自己持久化的设置。回退分三层:用户存过就用持久化的值;没存过就用你 <code>IConfigurable</code> schema 里该字段自己声明的 <code>DefaultValue</code>;两者都没有才轮到你传进来的 <code>defaultValue</code> 兜底——这样 schema 里声明的默认值就是唯一权威来源,调用方不需要在代码里再手写一份重复的默认值。如果你把某个设置缓存了起来而不是每次都重新读取,记得订阅 <code>SettingChanged(pluginId, key)</code> 事件,在它为你的插件触发时清空缓存——宿主是在设置页保存之后立刻触发这个事件的,这是唯一可靠的失效时机(不管是按键触发还是轮询检查,都要等到别的什么东西凑巧触发了才会看到变化,或者干脆永远看不到)。</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> —— 给数据是异步到达的 <code>IInstantResultProvider</code> 用的(参见 <a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>):等你的后台请求完成、结果也缓存好之后，调用这个方法并传入一个基于当前查询文字的判断函数，宿主会把所有匹配这个判断的、正在进行的搜索重新跑一遍，这样刚缓存好的结果就能直接显示出来，不需要用户重新输入。</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> —— 写入 App 的日志文件，和宿主自己的日志行一样，显示在<strong>设置 → 运行状态 → App</strong> 里。</td></tr><tr><td><code>PluginPromptService</code></td><td><code>Prompt(title, fields, initialValues?)</code> —— 弹出一个小的模态窗口，向用户询问给定<a href="./abstractions.html#iconfigurable"><code>PluginConfigField</code></a>字段的值(用的正是 <code>IConfigurable</code> 的配置对话框那套字段 schema/渲染逻辑)，按 <code>Key</code> 匹配从 <code>initialValues</code> 预填，没有就用各字段自己的 <code>DefaultValue</code>。返回按字段 <code>Key</code> 索引的填写结果，用户取消则返回 <code>null</code>——这些值不会读取或写入插件真正持久化的设置，所以可以放心复用某个配置字段的 schema 单纯做一次性输入(比如&quot;添加前先给它起个名字&quot;)，不会碰到背后真实的那个设置项。</td></tr></tbody></table><p><code>LogLevel</code> 是 <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>，与<a href="./../../user-guide/settings/service-status.html">运行状态日志查看器</a>里的等级过滤器一致。</p>',4)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
